"""
cleanup_and_finalize.py
------------------------
Run once from exploration-campaign-optimizer/:
  python cleanup_and_finalize.py

Writes all source files to their final state, clears pycache,
and removes all one-time patch scripts.
Then commit: git add . && git commit -m "message" && git push
"""
import os, base64, shutil

HERE = os.path.dirname(os.path.abspath(__file__))

# 1. Write all source files
FILES = {
    'src/well_heuristic.py': '',
    'src/well_visualizer.py': '',
    'src/well_solver.py': '',
    'src/well_ga.py': '',
    'src/well_gantt.py': '',
    'src/constraint_spec.py': '',
    'src/llm_formulator.py': '',
    'src/instance_builder.py': '',
    'data/snorre_parser.py': '',
    'main.py': '',
}
print("Writing source files...")
for rel, b64 in FILES.items():
    path = os.path.join(HERE, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print("  wrote", rel)

# 2. Clear pycache
print("\nClearing pycache...")
for d in ["src/__pycache__", "data/__pycache__", "__pycache__"]:
    full = os.path.join(HERE, d)
    if os.path.exists(full):
        shutil.rmtree(full)
        print("  cleared", d)

# 3. Remove patch scripts
TO_DELETE = ['setup_project.py', 'fix_instance_builder.py', 'add_heuristic.py', 'add_myopic.py', 'fix_csv_encoding.py', 'fix_visualizer.py', 'fix_visualizer2.py']
print("\nRemoving patch scripts...")
for f in TO_DELETE:
    path = os.path.join(HERE, f)
    if os.path.exists(path):
        os.remove(path)
        print("  removed", f)

print("\nAll done! Now run:")
print("  git add .")
print("  git commit -m \"Add heuristics + myopic greedy, clean up patch scripts\"")
print("  git push")
print("\nThen delete this file: del cleanup_and_finalize.py")